// </art:terrain>

const TERRAIN_DECOR_BY_CODE = {
  1: "grass", 2: "water", 3: "rubble", 4: "bones", 5: "mushroom",
  6: "moss", 7: "lamp", 8: "pike", 9: "crystal", 10: "pike"
};

const _terrainBgCache = new Map();

function _terrainPic(uriStr) {
  return 'url("' + uriStr + '")';
}

// Детерминированный выбор варианта: одна и та же клетка всегда получает
// свой тайл, а соседние — разные.
function terrainPick(list, x, y, salt) {
  if (!list || !list.length) return "";
  const n = list.length;
  return list[(((x * 7 + y * 13 + salt) % n) + n) % n];
}

// Направление, в котором «открыта» вода: по ней выбирается кадр волны.
function terrainWaveDir(x, y) {
  return ["E", "N", "S", "W"][(((x >> 1) + (y >> 1)) % 4 + 4) % 4];
}

// Зелень уместна на первых этажах: в склепе и логове дракона трава и мох
// заменяются камнем и костями, иначе посреди демонов растут кусты.
const TERRAIN_LATE_DECOR = { grass: "rubble", moss: "bones", mushroom: "bones" };

// В огненных этажах зелёные кости смотрятся чужими: там стоят колья с черепами.
const TERRAIN_INFERNAL_DECOR = { bones: "pike" };

// Человеческие имена декораций: по ним говорят проверки и подсказки.
const TERRAIN_DECOR_NAMES = {
  1: "трава", 2: "вода", 3: "обломки", 4: "кости", 5: "грибы",
  6: "мох", 7: "фонтан", 8: "кол", 9: "кристалл", 10: "череп на колу"
};

// Обитель демонов и логово дракона — огненные этажи: вода там лава.
function terrainIsInfernal(floorIdx) {
  const f = ((floorIdx % 10) + 10) % 10;
  return f === 6 || f === 9;
}

// Имя декора после замен по этажу (поздние этажи, огненные).
function terrainDecorName(floorIdx, code) {
  let name = TERRAIN_DECOR_BY_CODE[code];
  if (!name) return "";
  const f = ((floorIdx % 10) + 10) % 10;
  if (f >= 6 && TERRAIN_LATE_DECOR[name]) name = TERRAIN_LATE_DECOR[name];
  if (terrainIsInfernal(f) && TERRAIN_INFERNAL_DECOR[name]) name = TERRAIN_INFERNAL_DECOR[name];
  return name;
}

// Декор-«предметы»: колонны, фонтан, гриб, колья. Они стоят в клетке как вещь,
// а не лежат на полу, и спорили за взгляд с героем и монстрами: гриб принимали
// за монстра, белую колонну — за препятствие. Рисуются отдельным слоем с
// приглушением (см. .tile.has-obj в game.css); плоский декор — трава, мох,
// кристаллы, вода — остаётся в фоне плитки.
const TERRAIN_OBJECT_DECOR = { rubble: true, lamp: true, mushroom: true, pike: true, fire: true };

// Плитка-предмет для отдельного слоя либо "" — тогда декор лежит в фоне.
function terrainObjectUri(floorIdx, x, y, code) {
  const name = terrainDecorName(floorIdx, code);
  if (!name || !TERRAIN_OBJECT_DECOR[name]) return "";
  return terrainPick(TERRAIN_DECOR[name], x, y, 11);
}

// Пол под предметом: тот же, что в terrainBg, но без декора.
function terrainFloorBg(floorIdx, x, y) {
  return terrainBg(floorIdx, x, y, true, 0);
}

// Лавовая клетка-опасность: настоящая плитка лавы на любом этаже. Раньше это
// была оранжевая плёнка поверх пола, и безвредная декоративная лава выглядела
// опаснее настоящей. Кадры те же, что у лавы на огненных этажах.
function terrainLavaCellBg(x, y, frameIdx) {
  const skip = (x + y) % 2;
  const frames = [2, 3, 4, 5].map((i) => TERRAIN_LAVA[(i + skip) % TERRAIN_LAVA.length]);
  return _terrainPic(frames[(frameIdx || 0) % frames.length]);
}

function terrainDecorUri(floorIdx, x, y, code) {
  const name = terrainDecorName(floorIdx, code);
  if (!name) return "";
  const f = ((floorIdx % 10) + 10) % 10;
  if (name === "water") {
    // На огненных этажах вода — это лава.
    if (terrainIsInfernal(f)) return terrainPick(TERRAIN_LAVA, x, y, 3);
    return terrainPick(TERRAIN_WATER.base, x, y, 5);
  }
  return terrainPick(TERRAIN_DECOR[name], x, y, 11);
}

// Кадры анимации клетки: вода рябит, лава переливается, свет мигает.
function terrainAnimFrames(floorIdx, x, y, isFloor, code) {
  const name = TERRAIN_DECOR_BY_CODE[code];
  if (!isFloor || !name) return null;
  if (name === "water") {
    if (terrainIsInfernal(floorIdx)) {
      const skip = (x + y) % 2;
      return [2, 3, 4, 5].map((i) => TERRAIN_LAVA[(i + skip) % TERRAIN_LAVA.length]);
    }
    const dir = terrainWaveDir(x, y);
    const wave = TERRAIN_WATER.waves[dir] || TERRAIN_WATER.waves.E;
    // Основа — та же плитка воды, что и в статичном фоне (terrainDecorUri):
    // другая давала бы скачок картинки на первом же такте таймера.
    return [terrainPick(TERRAIN_WATER.base, x, y, 5), wave[0], wave[1]];
  }
  if (name === "lamp") return [TERRAIN_DECOR.lamp[0]];
  return null;
}

function terrainKind(floorIdx, code) {
  const name = TERRAIN_DECOR_BY_CODE[code];
  if (name === "water") return terrainIsInfernal(floorIdx) ? "lava" : "water";
  if (name === "lamp") return "light";
  return "";
}

// Тайлы для объектов на карте: лестницы, ловушки, сундук. Их подставляет
// mapIcon(). Ключ — поле icon ловушки из TRAP_TYPES (dungeon-content.js).
const TERRAIN_ICONS = {
  stairs: TERRAIN_STAIRS.down[0],
  stairsUp: TERRAIN_STAIRS.up[0],
  spikes: TERRAIN_TRAPS.spikes,
  pit: TERRAIN_TRAPS.pit,
  chain_snare: TERRAIN_TRAPS.net,
  mushroom_spore: TERRAIN_TRAPS.gas,
  crystal_shard: TERRAIN_TRAPS.blade,
  curse_tile: TERRAIN_TRAPS.magical,
  treasure: TERRAIN_OBJECTS.chest,
  // Тайлы деревни из того, что уже было в наборе, но лежало без дела: двери
  // (TERRAIN_DOORS не использовался нигде) и «фонтан» из декора — в деревне
  // он читается как колодец.
  door: TERRAIN_DOORS[0],
  doorLocked: TERRAIN_DOORS[1] || TERRAIN_DOORS[0],
  well: TERRAIN_DECOR.lamp[0],
  // Двор деревни: забор, бочка, поленница и труба нарисованы сборкой — в
  // наборе ничего похожего нет, а схематичные значки рядом с тайлами
  // выглядели заплатками. Костёр — готовый тайл огня из декора.
  campfire: TERRAIN_DECOR.fire[0],
  // Прогоревший костёр: тот же кадр, но приглушённый классом spent (см. game.css).
  campfireSpent: TERRAIN_DECOR.fire[0],
  fence: TERRAIN_VILLAGE.objects.fence,
  barrel: TERRAIN_VILLAGE.objects.barrel,
  woodpile: TERRAIN_VILLAGE.objects.woodpile,
  chimney: TERRAIN_VILLAGE.objects.chimney
};

// Материал клетки деревни → фон: крыша дома (с цветом и видом — конёк,
// скат или свес), фасад или окно. Материалы берутся из TERRAIN_VILLAGE,
// который собирает tools/art; в подземелье этой функции не зовут вовсе.
function villageTileUri(mat, kind, color, x, y) {
  if (!TERRAIN_VILLAGE) return "";
  if (mat === "roof") {
    const set = TERRAIN_VILLAGE.roofs[color] || TERRAIN_VILLAGE.roofs.red;
    if (!set) return "";
    const list = set[kind] || set.slope;
    if (!list || !list.length) return "";
    // Соседние клетки получают разные плитки — крыша не выглядит штампованной.
    return _terrainPic(list[((x * 7 + y * 13) % list.length + list.length) % list.length]);
  }
  if (mat === "window") return _terrainPic(TERRAIN_VILLAGE.window[0]);
  if (mat === "facade") return _terrainPic(TERRAIN_VILLAGE.wall[0]);
  return "";
}

function terrainIcon(key) {
  return TERRAIN_ICONS[key] || "";
}

// Фон клетки: готовый тайл пола или стены, поверх — декор.
function terrainBg(floorIdx, x, y, isFloor, decorCode) {
  const th = TERRAIN_FLOORS[((floorIdx % TERRAIN_FLOORS.length) +
    TERRAIN_FLOORS.length) % TERRAIN_FLOORS.length];
  const ck = floorIdx + "|" + x + "|" + y + "|" + (isFloor ? "f" : "w") + "|" + decorCode;
  const hit = _terrainBgCache.get(ck);
  if (hit !== undefined) return hit;
  const salt = (x * 31 + y * 17) % 251;
  let bg = _terrainPic(isFloor ? terrainPick(th.floor, x, y, salt)
                               : terrainPick(th.wall, x, y, salt));
  if (isFloor && decorCode) {
    const decor = terrainDecorUri(floorIdx, x, y, decorCode);
    if (decor) bg = _terrainPic(decor) + ", " + bg;
  }
  _terrainBgCache.set(ck, bg);
  return bg;
}

// Строка фона для кадра анимации: декор + тот же пол.
function terrainAnimBg(floorIdx, x, y, isFloor, code, frameIdx) {
  const frames = terrainAnimFrames(floorIdx, x, y, isFloor, code);
  if (!frames) return "";
  const th = TERRAIN_FLOORS[((floorIdx % TERRAIN_FLOORS.length) +
    TERRAIN_FLOORS.length) % TERRAIN_FLOORS.length];
  const under = _terrainPic(terrainPick(th.floor, x, y, (x * 31 + y * 17) % 251));
  const i = frameIdx % frames.length;
  let top = _terrainPic(frames[i]);
  // Кадры волны нарисованы одними штрихами, без воды под ними: поверх голого
  // пола они давали белую «молнию» на земле в двух кадрах из трёх. Под волну
  // кладём плитку воды (нулевой кадр); лава на огненных этажах целая.
  if (i > 0 && TERRAIN_DECOR_BY_CODE[code] === "water" && !terrainIsInfernal(floorIdx)) {
    top += ", " + _terrainPic(frames[0]);
  }
  return top + ", " + under;
}
